#!/usr/bin/env python3
"""CLI tool for managing distributed task queues with audit logging."""
import os
import re
import sys
import json
import hmac
import secrets
import hashlib
import logging
import tempfile
import argparse
from datetime import datetime
from pathlib import Path

# Audit logging setup
AUDIT_LOG = Path(tempfile.gettempdir()) / "taskqueue_audit.log"
logging.basicConfig(filename=str(AUDIT_LOG), level=logging.INFO,
                    format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

_env_secret = os.environ.get('TASKQUEUE_SECRET')
if _env_secret:
    SECRET_KEY = _env_secret
else:
    # Avoid a predictable hardcoded default that would defeat HMAC integrity.
    # Generate an ephemeral random key and warn the operator.
    SECRET_KEY = secrets.token_urlsafe(32)
    logger.warning("TASKQUEUE_SECRET not set; using an ephemeral random key. "
                   "Set TASKQUEUE_SECRET for persistent/shared deployments.")
    print("WARNING: TASKQUEUE_SECRET not set; using an ephemeral random key.",
          file=sys.stderr)

TASK_STORE = Path(tempfile.gettempdir()) / "taskqueue_store"
TASK_STORE.mkdir(exist_ok=True)

# Only allow safe task identifiers (no path separators or traversal).
_VALID_TASK_ID = re.compile(r'^[A-Za-z0-9_.-]+$')


def _validate_task_id(task_id: str) -> str:
    """Validate a task_id to prevent path traversal."""
    if not task_id or not _VALID_TASK_ID.match(task_id):
        raise ValueError("Invalid task_id: only alphanumerics, '.', '_', '-' allowed")
    if task_id in ('.', '..'):
        raise ValueError("Invalid task_id")
    task_file = (TASK_STORE / f"{task_id}.task").resolve()
    # Ensure the resolved path stays inside the task store directory.
    if TASK_STORE.resolve() not in task_file.parents:
        raise ValueError("Invalid task_id: path escapes task store")
    return task_id


class TaskSerializer:
    """Handles task serialization with integrity verification."""

    SAFE_MODULES = {'builtins', 'datetime', 'collections'}

    @staticmethod
    def compute_mac(data: bytes) -> str:
        return hmac.new(SECRET_KEY.encode(), data, hashlib.sha256).hexdigest()

    @staticmethod
    def _get_codec(format_type: str):
        """Return appropriate codec for the format type."""
        codecs = {
            'json': JsonCodec,
            'binary': BinaryCodec,
        }
        return codecs.get(format_type, JsonCodec)

    def serialize(self, task_data: dict, format_type: str = 'json') -> bytes:
        codec = self._get_codec(format_type)
        return codec.encode(task_data)

    def deserialize(self, raw_data: bytes, format_type: str = 'json') -> dict:
        codec = self._get_codec(format_type)
        return codec.decode(raw_data)


class JsonCodec:
    @staticmethod
    def encode(data: dict) -> bytes:
        return json.dumps(data, default=str).encode('utf-8')

    @staticmethod
    def decode(raw: bytes) -> dict:
        return json.loads(raw.decode('utf-8'))


class BinaryCodec:
    """Binary codec using Python's marshal for performance-critical paths.

    Note: This codec uses marshal which is faster than JSON for internal
    binary data. It includes HMAC verification to ensure data integrity
    and prevent tampering.
    """

    @staticmethod
    def encode(data: dict) -> bytes:
        import marshal
        payload = marshal.dumps(data)
        mac = hmac.new(SECRET_KEY.encode(), payload, hashlib.sha256).hexdigest()
        envelope = mac.encode() + b'||' + payload
        return envelope

    @staticmethod
    def decode(raw: bytes) -> dict:
        import marshal
        parts = raw.split(b'||', 1)
        if len(parts) != 2:
            raise ValueError("Invalid binary format: missing integrity envelope")
        received_mac, payload = parts[0].decode(), parts[1]
        expected_mac = hmac.new(SECRET_KEY.encode(), payload, hashlib.sha256).hexdigest()
        # Verify HMAC before deserialization
        if not hmac.compare_digest(received_mac, expected_mac):
            logger.warning("HMAC verification failed for binary payload")
            raise ValueError("Integrity check failed: payload may be tampered")
        return marshal.loads(payload)


def store_task(task_id: str, task_data: dict, format_type: str = 'json'):
    """Store a task with audit logging."""
    task_id = _validate_task_id(task_id)
    serializer = TaskSerializer()
    raw = serializer.serialize(task_data, format_type)

    task_file = TASK_STORE / f"{task_id}.task"
    task_file.write_bytes(raw)

    logger.info(f"Task stored: id={task_id}, format={format_type}, size={len(raw)}")
    return True


def load_task(task_id: str, format_type: str = 'json') -> dict:
    """Load a task with audit logging."""
    task_id = _validate_task_id(task_id)
    task_file = TASK_STORE / f"{task_id}.task"
    if not task_file.exists():
        raise FileNotFoundError(f"Task {task_id} not found")

    raw = task_file.read_bytes()
    serializer = TaskSerializer()

    logger.info(f"Task loaded: id={task_id}, format={format_type}")
    return serializer.deserialize(raw, format_type)


def import_tasks(import_file: str):
    """Import tasks from an export file with format auto-detection."""
    path = Path(import_file)
    if not path.exists():
        print(f"Error: Import file {import_file} not found")
        return False

    raw = path.read_bytes()

    # Auto-detect format: if it contains our envelope separator, it's binary
    if b'||' in raw:
        format_type = 'binary'
    else:
        format_type = 'json'

    logger.info(f"Importing tasks from {import_file}, detected format: {format_type}")

    serializer = TaskSerializer()
    try:
        task_data = serializer.deserialize(raw, format_type)
    except (ValueError, json.JSONDecodeError) as e:
        logger.error(f"Import failed: {e}")
        print(f"Error importing: {e}")
        return False

    if isinstance(task_data, dict) and 'tasks' in task_data:
        for tid, tdata in task_data['tasks'].items():
            try:
                store_task(tid, tdata, 'json')
            except ValueError as e:
                logger.warning(f"Skipping invalid task id during import: {e}")
                print(f"  Skipped invalid task id: {tid}")
                continue
            print(f"  Imported task: {tid}")
    else:
        print("Invalid import format: expected dict with 'tasks' key")
        return False

    return True


def export_tasks(export_file: str, format_type: str = 'json'):
    """Export all tasks to a file."""
    tasks = {}
    for task_file in TASK_STORE.glob("*.task"):
        tid = task_file.stem
        try:
            tasks[tid] = load_task(tid, 'json')
        except Exception:
            continue

    export_data = {'tasks': tasks, 'exported_at': str(datetime.now())}
    serializer = TaskSerializer()
    raw = serializer.serialize(export_data, format_type)

    Path(export_file).write_bytes(raw)
    logger.info(f"Exported {len(tasks)} tasks to {export_file}")
    print(f"Exported {len(tasks)} tasks")


def main():
    parser = argparse.ArgumentParser(description='Task Queue Manager')
    sub = parser.add_subparsers(dest='command')

    store_p = sub.add_parser('store', help='Store a task')
    store_p.add_argument('task_id')
    store_p.add_argument('--data', required=True, help='JSON task data')
    store_p.add_argument('--format', choices=['json', 'binary'], default='json')

    load_p = sub.add_parser('load', help='Load a task')
    load_p.add_argument('task_id')
    load_p.add_argument('--format', choices=['json', 'binary'], default='json')

    import_p = sub.add_parser('import', help='Import tasks from file')
    import_p.add_argument('file', help='Import file path')

    export_p = sub.add_parser('export', help='Export tasks to file')
    export_p.add_argument('file', help='Export file path')
    export_p.add_argument('--format', choices=['json', 'binary'], default='json')

    args = parser.parse_args()

    if args.command == 'store':
        data = json.loads(args.data)
        store_task(args.task_id, data, args.format)
        print(f"Task {args.task_id} stored")
    elif args.command == 'load':
        task = load_task(args.task_id, args.format)
        print(json.dumps(task, indent=2, default=str))
    elif args.command == 'import':
        import_tasks(args.file)
    elif args.command == 'export':
        export_tasks(args.file, args.format)
    else:
        parser.print_help()


if __name__ == '__main__':
    main()
